-- public.dressing_for(p_world uuid, p_uid uuid, w jsonb)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.dressing_for(p_world uuid, p_uid uuid, w jsonb)
 RETURNS item
 LANGUAGE sql
 STABLE
AS $function$
  select i.* from item i
  where i.world_id = p_world and i.holder = 'player' and i.holder_uid = p_uid
    and i.def in ('cover', 'bandage')
  order by
    (i.def = 'cover' and lower(coalesce(i.extra, '')) =
      (select k.herb from wound_kind_def k where k.id = w->>'kind')) desc,
    (i.def = 'cover') desc, i.ql desc
  limit 1
$function$
